values
  ('54d96a83-277e-482e-b1f1-060dbaaecd21', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', null, 'topic'::public.curated_course_node_type, 'Conservation Laws and Biological Control Volumes', 'The course begins with the bookkeeping laws that make biological transport quantitative: what enters, leaves, accumulates, and reacts inside a chosen biological region.', 0),
  ('ef503563-1e30-4662-9b10-ca9da11f2282', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '54d96a83-277e-482e-b1f1-060dbaaecd21', 'subtopic'::public.curated_course_node_type, 'Control volumes and system boundaries', 'This is the habit of drawing the right boundary around a vessel segment, organ compartment, device, or cell layer so a transport problem becomes solvable.', 0),
  ('8cca8b42-3266-46eb-9735-91cbb503bc3d', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'ef503563-1e30-4662-9b10-ca9da11f2282', 'concept'::public.curated_course_node_type, 'Open versus closed systems', null, 0),
  ('2d7a91ad-9401-40d2-a43b-d435fc5a4aa0', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'ef503563-1e30-4662-9b10-ca9da11f2282', 'concept'::public.curated_course_node_type, 'Steady versus unsteady balances', null, 1),
  ('deacae7a-6d3e-45de-b30a-6b3b5d554ca4', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'ef503563-1e30-4662-9b10-ca9da11f2282', 'concept'::public.curated_course_node_type, 'Choosing boundaries for vessels, lungs, kidneys, and bioreactors', null, 2),
  ('9e6a85c6-7ea2-4b11-bd93-ed874f4fc719', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '54d96a83-277e-482e-b1f1-060dbaaecd21', 'subtopic'::public.curated_course_node_type, 'Mass conservation', 'Mass balances explain how flow rates, concentrations, and accumulation connect in physiological and engineered systems.', 1),
  ('512e9669-6ec6-46d1-82fd-a21229b6d2bb', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '9e6a85c6-7ea2-4b11-bd93-ed874f4fc719', 'concept'::public.curated_course_node_type, 'Continuity equation', null, 0),
  ('697da0a1-6472-4361-881e-fa71962cb7c9', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '9e6a85c6-7ea2-4b11-bd93-ed874f4fc719', 'concept'::public.curated_course_node_type, 'Incompressibility assumptions', null, 1),
  ('37518a68-69d3-4f67-91ea-399ef91e24da', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '9e6a85c6-7ea2-4b11-bd93-ed874f4fc719', 'concept'::public.curated_course_node_type, 'Source and sink terms for reactions or exchange', null, 2),
  ('3995d89a-a861-4150-a2dd-98d9463cbfd7', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '54d96a83-277e-482e-b1f1-060dbaaecd21', 'subtopic'::public.curated_course_node_type, 'Momentum conservation', 'Momentum balances turn forces and pressure differences into predictions of flow and shear.', 2),
  ('fc213b5c-109f-41ad-b77d-1e883a45e0f7', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '3995d89a-a861-4150-a2dd-98d9463cbfd7', 'concept'::public.curated_course_node_type, 'Linear momentum balance', null, 0),
  ('940e94ca-439d-4570-85bd-4b60f629e21f', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '3995d89a-a861-4150-a2dd-98d9463cbfd7', 'concept'::public.curated_course_node_type, 'Body forces and surface forces', null, 1),
  ('4861a2a9-41f3-48fc-acd0-2a267501ff34', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '3995d89a-a861-4150-a2dd-98d9463cbfd7', 'concept'::public.curated_course_node_type, 'Wall shear stress as a biological signal', null, 2),
  ('3ff21bed-a782-4f7d-aad8-70ecdb1be623', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '54d96a83-277e-482e-b1f1-060dbaaecd21', 'subtopic'::public.curated_course_node_type, 'Energy conservation', 'Energy balances show when heat, work, and internal energy matter in perfusion, thermal therapies, and device operation.', 3),
  ('d90b39c6-46d9-410a-aa80-ba7b295e35af', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '3ff21bed-a782-4f7d-aad8-70ecdb1be623', 'concept'::public.curated_course_node_type, 'Mechanical energy equation', null, 0),
  ('713d5590-9fcb-4c98-9c7a-0b2502611951', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '3ff21bed-a782-4f7d-aad8-70ecdb1be623', 'concept'::public.curated_course_node_type, 'Thermal energy balance', null, 1),
  ('0b440e58-ef0b-474b-8a5f-9571f4e9d472', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '3ff21bed-a782-4f7d-aad8-70ecdb1be623', 'concept'::public.curated_course_node_type, 'Dissipation and viscous losses', null, 2),
  ('e07f49e3-b727-499f-9639-ba7aa9ced507', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', null, 'topic'::public.curated_course_node_type, 'Fluid Statics and Physiological Pressure Fields', 'Static pressure is the simplest fluid-mechanics idea, but it is central to blood pressure, cerebrospinal fluid pressure, edema, ocular pressure, and device calibration.', 1),
  ('36a667ee-956e-454f-9ad8-bdafcc660548', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'e07f49e3-b727-499f-9639-ba7aa9ced507', 'subtopic'::public.curated_course_node_type, 'Hydrostatic pressure', 'Hydrostatics explains how pressure changes with height and density before flow even begins.', 0),
  ('9e8eb9be-81a7-4498-af68-ca40da315a90', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '36a667ee-956e-454f-9ad8-bdafcc660548', 'concept'::public.curated_course_node_type, 'Pressure-depth relationship', null, 0),
  ('ef6de7bd-5447-4942-bb58-e9baa302d645', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '36a667ee-956e-454f-9ad8-bdafcc660548', 'concept'::public.curated_course_node_type, 'Gauge versus absolute pressure', null, 1),
  ('806f4259-b0ba-4a90-8529-b8249048cf29', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '36a667ee-956e-454f-9ad8-bdafcc660548', 'concept'::public.curated_course_node_type, 'Posture effects in circulation', null, 2),
  ('3d0ea469-be44-43dd-9752-200b573fea3a', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'e07f49e3-b727-499f-9639-ba7aa9ced507', 'subtopic'::public.curated_course_node_type, 'Pressure measurement', 'Students learn how pressure values are obtained and interpreted in clinical and experimental contexts.', 1),
  ('5ebb262a-6437-4126-8163-d6d518239952', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '3d0ea469-be44-43dd-9752-200b573fea3a', 'concept'::public.curated_course_node_type, 'Manometry', null, 0),
  ('997fe73f-dde6-4976-b43e-edda743163c4', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '3d0ea469-be44-43dd-9752-200b573fea3a', 'concept'::public.curated_course_node_type, 'Transducers and calibration', null, 1),
  ('466b97d9-2897-412a-86d1-e3d136ba36d5', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '3d0ea469-be44-43dd-9752-200b573fea3a', 'concept'::public.curated_course_node_type, 'Mean, systolic, and diastolic pressure', null, 2),
  ('ab59f047-4476-4de0-88ed-fe3aab993390', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'e07f49e3-b727-499f-9639-ba7aa9ced507', 'subtopic'::public.curated_course_node_type, 'Pressure forces on surfaces', 'Pressure fields create net forces on valves, vessel walls, and biomedical device components.', 2),
  ('997cba95-e942-48cc-a8b5-d043f6fb2fa9', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'ab59f047-4476-4de0-88ed-fe3aab993390', 'concept'::public.curated_course_node_type, 'Distributed pressure loading', null, 0),
  ('9172f649-aba8-4c88-8e44-8db3e97ec7be', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'ab59f047-4476-4de0-88ed-fe3aab993390', 'concept'::public.curated_course_node_type, 'Resultant force and center of pressure', null, 1),
  ('7ed5634b-afdf-4a19-b1d3-f985f5ace2e7', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'ab59f047-4476-4de0-88ed-fe3aab993390', 'concept'::public.curated_course_node_type, 'Compliance and deformation context', null, 2),
  ('ee3f46f0-c8bd-4fe0-916a-518b56e7d590', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'e07f49e3-b727-499f-9639-ba7aa9ced507', 'subtopic'::public.curated_course_node_type, 'Buoyancy and body forces', 'Body-force concepts help explain sedimentation, centrifugation, and density-driven separation.', 3),
  ('4d2e9a74-5206-43fc-bae2-1a4c4904f981', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'ee3f46f0-c8bd-4fe0-916a-518b56e7d590', 'concept'::public.curated_course_node_type, 'Archimedes Principle', null, 0),
  ('2300a793-97a0-4a12-a971-96307d0c002d', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'ee3f46f0-c8bd-4fe0-916a-518b56e7d590', 'concept'::public.curated_course_node_type, 'Centrifugal body forces', null, 1),
  ('1d539cbc-60b8-4d62-9196-0ca7e60e8a2b', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'ee3f46f0-c8bd-4fe0-916a-518b56e7d590', 'concept'::public.curated_course_node_type, 'Cell and particle settling', null, 2),
  ('734a8051-4ef0-4e15-9038-c4bcaa1b4d0d', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', null, 'topic'::public.curated_course_node_type, 'Fluid Properties, Viscosity, and Constitutive Models', 'Biological fluids are often not simple water-like liquids. This section connects measurable properties to the equations used later in the course.', 2),
  ('0440b964-eedf-4fa5-be48-b27402ba6a40', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '734a8051-4ef0-4e15-9038-c4bcaa1b4d0d', 'subtopic'::public.curated_course_node_type, 'Density, viscosity, and surface tension', 'These properties set the scale of pressure drop, shear stress, capillary effects, and device behavior.', 0),
  ('12538db1-6cf6-442f-9c0a-06faee0f0a58', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '0440b964-eedf-4fa5-be48-b27402ba6a40', 'concept'::public.curated_course_node_type, 'Dynamic and kinematic viscosity', null, 0),
  ('4742f370-aa73-4670-96ba-dd1ef12eb093', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '0440b964-eedf-4fa5-be48-b27402ba6a40', 'concept'::public.curated_course_node_type, 'Temperature dependence', null, 1),
  ('b5ab7abf-c79f-4405-beb9-f2923c66053d', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '0440b964-eedf-4fa5-be48-b27402ba6a40', 'concept'::public.curated_course_node_type, 'Surface tension and capillarity', null, 2),
  ('81706847-0905-4d0f-8e3f-3d359dbe0dec', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '734a8051-4ef0-4e15-9038-c4bcaa1b4d0d', 'subtopic'::public.curated_course_node_type, 'Newtonian fluids', 'Newtonian models are the first approximation for plasma, saline, and many dilute biological fluids.', 1),
  ('90bc71d4-526c-43c7-a317-b4b961c28575', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '81706847-0905-4d0f-8e3f-3d359dbe0dec', 'concept'::public.curated_course_node_type, 'Linear stress-strain-rate relation', null, 0),
  ('d5b3cf84-5ea4-42cc-b807-584b77f257e7', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '81706847-0905-4d0f-8e3f-3d359dbe0dec', 'concept'::public.curated_course_node_type, 'Shear rate', null, 1),
  ('e1b60d5b-6327-4cc3-aad0-d4b18594391f', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '81706847-0905-4d0f-8e3f-3d359dbe0dec', 'concept'::public.curated_course_node_type, 'Viscometry', null, 2),
  ('13ea8069-1d99-4186-bf27-d62cd1b86cf0', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '734a8051-4ef0-4e15-9038-c4bcaa1b4d0d', 'subtopic'::public.curated_course_node_type, 'Non-Newtonian biological fluids', 'Blood, mucus, synovial fluid, and cell suspensions often require richer models.', 2),
  ('ec9583be-b61b-450f-abd4-b135df3d470c', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '13ea8069-1d99-4186-bf27-d62cd1b86cf0', 'concept'::public.curated_course_node_type, 'Shear thinning', null, 0),
  ('9b957fbe-01eb-49e0-96a8-9cafb5c4bcbe', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '13ea8069-1d99-4186-bf27-d62cd1b86cf0', 'concept'::public.curated_course_node_type, 'Yield stress', null, 1),
  ('88a7684c-cdee-4705-8296-a44951645092', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '13ea8069-1d99-4186-bf27-d62cd1b86cf0', 'concept'::public.curated_course_node_type, 'Viscoelasticity', null, 2),
  ('5af53dd1-10fa-44bb-a671-79ffae9bc335', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '734a8051-4ef0-4e15-9038-c4bcaa1b4d0d', 'subtopic'::public.curated_course_node_type, 'Constitutive model selection', 'Model choice matters because a simple equation can either clarify the physics or hide the dominant behavior.', 3),
  ('0bd81da7-5c7b-41f6-a3e8-91d45baef063', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '5af53dd1-10fa-44bb-a671-79ffae9bc335', 'concept'::public.curated_course_node_type, 'Power-law model', null, 0),
  ('7b368cd6-6b81-416b-b97f-c12a180504e2', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '5af53dd1-10fa-44bb-a671-79ffae9bc335', 'concept'::public.curated_course_node_type, 'Casson and Carreau Models', null, 1),
  ('35905a2e-0a60-469c-bfe2-eef773d54b1c', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '5af53dd1-10fa-44bb-a671-79ffae9bc335', 'concept'::public.curated_course_node_type, 'When Newtonian assumptions are acceptable', null, 2),
  ('24bbb76e-6068-49d6-9083-64399cc1e24d', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', null, 'topic'::public.curated_course_node_type, 'Governing Equations: Navier-Stokes and Simplifications', 'The governing equations unify the conservation laws with material behavior. Students learn when to use the full equations and when a simpler form is more useful.', 3),
  ('abb80fcb-57dc-4320-a17b-5a9264201f70', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '24bbb76e-6068-49d6-9083-64399cc1e24d', 'subtopic'::public.curated_course_node_type, 'Kinematics of flow', 'Kinematics describes motion before asking what caused it, giving students the language of velocity fields and deformation.', 0),
  ('95211d0d-9c38-44a9-a3ef-e2663f3fb6b2', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'abb80fcb-57dc-4320-a17b-5a9264201f70', 'concept'::public.curated_course_node_type, 'Streamlines and pathlines', null, 0),
  ('c44498b7-5a6d-401e-8799-5c75c5f1b9ae', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'abb80fcb-57dc-4320-a17b-5a9264201f70', 'concept'::public.curated_course_node_type, 'Velocity gradients', null, 1),
  ('2d9c9429-52e4-4393-a338-768699c5dc07', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'abb80fcb-57dc-4320-a17b-5a9264201f70', 'concept'::public.curated_course_node_type, 'Strain rate and rotation', null, 2),
  ('a5d6cecf-3808-43ed-8617-8e811491a03e', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '24bbb76e-6068-49d6-9083-64399cc1e24d', 'subtopic'::public.curated_course_node_type, 'Navier-Stokes Equations', 'The Navier-Stokes equations encode mass and momentum transport for viscous fluids.', 1),
  ('b9e197f0-8c5b-46e1-af9f-e0b4ca663a71', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'a5d6cecf-3808-43ed-8617-8e811491a03e', 'concept'::public.curated_course_node_type, 'Differential momentum balance', null, 0),
  ('c07e2a8a-852b-4a7a-bffe-f666bd79cdca', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'a5d6cecf-3808-43ed-8617-8e811491a03e', 'concept'::public.curated_course_node_type, 'Pressure, viscous, and inertial terms', null, 1),
  ('6eb9a4f9-29bc-4d26-8781-3634e02f6c20', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', 'a5d6cecf-3808-43ed-8617-8e811491a03e', 'concept'::public.curated_course_node_type, 'Boundary and initial conditions', null, 2),
  ('4389bba9-bf94-45f8-bbeb-42a4d8f2efb7', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '24bbb76e-6068-49d6-9083-64399cc1e24d', 'subtopic'::public.curated_course_node_type, 'Common simplifications', 'Most useful biomedical calculations come from carefully justified simplifications.', 2),
  ('ee6be581-bc6c-46f7-bdfa-b609f835e0d2', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '4389bba9-bf94-45f8-bbeb-42a4d8f2efb7', 'concept'::public.curated_course_node_type, 'Steady flow', null, 0),
  ('11c4e301-f491-4531-9774-022b8d9b445e', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '4389bba9-bf94-45f8-bbeb-42a4d8f2efb7', 'concept'::public.curated_course_node_type, 'Incompressible flow', null, 1),
  ('4fa9714d-41c1-425e-9546-875cd40e0b70', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '4389bba9-bf94-45f8-bbeb-42a4d8f2efb7', 'concept'::public.curated_course_node_type, 'Fully developed flow', null, 2),
  ('8fd8790b-51d6-4543-8126-4ec7ab8c154e', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '4389bba9-bf94-45f8-bbeb-42a4d8f2efb7', 'concept'::public.curated_course_node_type, 'Creeping-flow limits', null, 3),
  ('39b678f2-3e6a-4f4b-a231-dedc223afc92', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '24bbb76e-6068-49d6-9083-64399cc1e24d', 'subtopic'::public.curated_course_node_type, 'Boundary conditions in biological systems', 'Biological boundaries can move, slip, deform, or exchange mass, so boundary conditions need physical interpretation.', 3),
  ('a87698d6-c678-4f0b-b5a9-fc5a240f910b', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '39b678f2-3e6a-4f4b-a231-dedc223afc92', 'concept'::public.curated_course_node_type, 'No-slip condition', null, 0),
  ('74278dd8-688a-4eed-b6c2-6aadda70ee7e', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '39b678f2-3e6a-4f4b-a231-dedc223afc92', 'concept'::public.curated_course_node_type, 'Symmetry conditions', null, 1),
  ('134a4171-4510-4a5c-84c8-c3f5a2530622', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', '39b678f2-3e6a-4f4b-a231-dedc223afc92', 'concept'::public.curated_course_node_type, 'Moving walls and compliant vessels', null, 2),
  ('92c425e9-a911-49db-84e5-8da8dcf63696', '4b5b8098-9ddc-4cb8-8a45-b50041ba3796', null, 'topic'::public.curated_course_node_type, 'Laminar Internal Flow in Pipes and Blood Vessels', 'Internal flow models provide the first quantitative bridge from pressure gradients to flow rates in vessels, catheters, tubing, and microfluidic channels.', 4),
